solution.python:
def search(nums: list[int], target: int) -> int:
    left, right = 0, len(nums) - 1
    # The candidate range includes both endpoints.
    while left <= right:
        mid = left + (right - left) // 2
        if nums[mid] == target:
            return mid
        if nums[mid] < target:
            left = mid + 1  # Discard the middle and smaller values.
        else:
            right = mid - 1
    return -1

solution.java:
class Solution {
    public int search(int[] nums, int target) {
        int left = 0, right = nums.length - 1;
        // The candidate range includes both endpoints.
        while (left <= right) {
            int mid = left + (right - left) / 2;
            if (nums[mid] == target) {
                return mid;
            }
            if (nums[mid] < target) {
                left = mid + 1; // Discard the middle and smaller values.
            } else {
                right = mid - 1;
            }
        }
        return -1;
    }
}

solution.javascript:
function search(nums, target) {
    let left = 0, right = nums.length - 1;
    // The candidate range includes both endpoints.
    while (left <= right) {
        const mid = left + Math.floor((right - left) / 2);
        if (nums[mid] === target) {
            return mid;
        }
        if (nums[mid] < target) {
            left = mid + 1; // Discard the middle and smaller values.
        } else {
            right = mid - 1;
        }
    }
    return -1;
}
